-- =============================================================================
-- CampusHarmony — Realistic Academic Demonstration Dataset (seed.sql)
-- Fully Idempotent Seed File with 300 Students, 15 Teachers, 5 Sections
-- =============================================================================

USE campus_harmony;

SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE complaint_activity;
TRUNCATE TABLE complaints;
TRUNCATE TABLE assessment_marks;
TRUNCATE TABLE assessments;
TRUNCATE TABLE attendance_records;
TRUNCATE TABLE attendance_sessions;
TRUNCATE TABLE timetable_entries;
TRUNCATE TABLE course_enrollments;
TRUNCATE TABLE course_offerings;
TRUNCATE TABLE section_members;
DELETE FROM accounts WHERE role IN ('teacher', 'student');
TRUNCATE TABLE students;
TRUNCATE TABLE teachers;
TRUNCATE TABLE sections;
SET FOREIGN_KEY_CHECKS = 1;

-- 1. Departments
ON DUPLICATE KEY UPDATE name=VALUES(name), code=VALUES(code);

-- 2. Academic Periods
ON DUPLICATE KEY UPDATE name=VALUES(name), is_current=VALUES(is_current);

-- 3. Academic Programs
ON DUPLICATE KEY UPDATE name=VALUES(name), degree=VALUES(degree), duration_years=VALUES(duration_years);

-- 4. Curricular Subjects
ON DUPLICATE KEY UPDATE label=VALUES(label);

-- 5. Courses
ON DUPLICATE KEY UPDATE name=VALUES(name), credits=VALUES(credits), semester=VALUES(semester), faculty=VALUES(faculty);

-- 6. 15 Faculty Members
ON DUPLICATE KEY UPDATE name=VALUES(name), subject=VALUES(subject);

ON DUPLICATE KEY UPDATE display_name=VALUES(display_name), password_hash=VALUES(password_hash);

-- Administrator Account
ON DUPLICATE KEY UPDATE display_name=VALUES(display_name), password_hash=VALUES(password_hash);

-- 7. Academic Sections
ON DUPLICATE KEY UPDATE name=VALUES(name), program_id=VALUES(program_id), mentor_teacher_id=VALUES(mentor_teacher_id);

-- 8. 25 Course Offerings
ON DUPLICATE KEY UPDATE teacher_id=VALUES(teacher_id);

-- 9. 300 Students
ON DUPLICATE KEY UPDATE name=VALUES(name), email=VALUES(email), phone=VALUES(phone), program_id=VALUES(program_id), teacher_id=VALUES(teacher_id);

ON DUPLICATE KEY UPDATE section_id=VALUES(section_id);

ON DUPLICATE KEY UPDATE display_name=VALUES(display_name), password_hash=VALUES(password_hash);

-- 10. 1,500 Course Enrollments
ON DUPLICATE KEY UPDATE status=VALUES(status);

-- 11. Timetable Entries (Zero Conflicts)
ON DUPLICATE KEY UPDATE room=VALUES(room), is_active=VALUES(is_active);

-- 12. Attendance Sessions
ON DUPLICATE KEY UPDATE submitted_at=VALUES(submitted_at), status=VALUES(status);

